SELECT g.INDX_CNAME AS `指数名称`, g.INDX_CODE AS `指数代码`, f.ENDDATE AS `报告期`, ROUND(f.ROE, 2) AS `净资产收益率(%)` FROM ANA_INDX_FIN_IDX f INNER JOIN GET_INDX_GEN_INFO g ON f.INNER_CODE = g.INNER_CODE WHERE (g.INDX_CNAME LIKE '%深证100%' OR g.INDX_CODE = '000852') AND f.ENDDATE = '2026-06-30 00:00:00.000' AND g.USE_STATUS = '使用' AND g.ISVALID = 1 AND f.ISVALID = 1 AND f.ROE IS NOT NULL ORDER BY f.ROE DESC;
